class ProductUnit { final String id; final String label; final String baseUnit; final int scale; final int defaultStepBase; const ProductUnit(this.id,this.label,this.baseUnit,this.scale,this.defaultStepBase); static const pieces=ProductUnit('piece','قطعة','piece',1,1); static const kilogram=ProductUnit('kg','كجم','g',1000,250); static const gram=ProductUnit('g','جرام','g',1,50); static const liter=ProductUnit('l','لتر','ml',1000,250); static const milliliter=ProductUnit('ml','مل','ml',1,50); static const meter=ProductUnit('m','متر','m',1,1); static const all=[pieces,kilogram,gram,liter,milliliter,meter]; static ProductUnit fromId(String? id)=>all.firstWhere((u)=>u.id==id,orElse:()=>pieces); static ProductUnit fromProduct(Map<String,dynamic> d)=>fromId((d['saleUnit']??d['unit']??d['unitId'])?.toString()); double toBase(num q)=>(q*scale).toDouble(); double fromBase(num q)=>q/scale; int stepFor(Map<String,dynamic>d)=>d['stepBase'] is num&&d['stepBase']>0?(d['stepBase'] as num).round():defaultStepBase; int minFor(Map<String,dynamic>d)=>d['minOrderBase'] is num&&d['minOrderBase']>0?(d['minOrderBase'] as num).round():stepFor(d); static int stockBase(Map<String,dynamic>d){final u=fromProduct(d);if(d['stockBase'] is num)return(d['stockBase'] as num).round();final s=d['stock'];return s is num?(s*u.scale).round():0;} static String formatBase(Map<String,dynamic>d,num q){final u=fromProduct(d);return '${u.fromBase(q)} ${u.label}';} }